			{y0*side + x0, (1 - fy) * (1 - fx)},
			{y0*side + x1, (1 - fy) * fx},
			{y1*side + x0, fy * (1 - fx)},
			{y1*side + x1, fy * fx},
		} {
			if c.w == 0 {
				continue
			}
			row := m.PosEmbed[c.idx*dim : (c.idx+1)*dim]
			for i, v := range row {
				dst[i] += float32(c.w * float64(v))
			}
		}
	}
	return out, nil
}

// srcCoord is align_corners=true's destination-to-source map.
func srcCoord(i, n, side int) float64 {
	if n <= 1 {
		return 0
	}
	return float64(i) * float64(side-1) / float64(n-1)
}

// Rope is the tower's axial 2-D rotary table: cos and sin of [tokens,
// headDim], already in the layout the rotation reads.
//
// The frequencies are built over headDim/2 = 36 with a stride of 2, giving
// 18 per axis; h's 18 and w's 18 are concatenated to 36 and the 36
// duplicated to 72. The rotation is then **NeoX halves** -- the first half
// of the head against the second -- and not the adjacent-pair complex
// rotation the DiT's RoPE uses. Both conventions live in this repository
// and swapping them is a negative control in dit_test.go for exactly that
// reason.
type Rope struct {
	Cos, Sin *qwen.Mat
	// Pairs selects the *other* convention -- adjacent-pair complex
	// rotation, which is what qimage/dit's RoPE does. It is wrong here and
	// is selectable for exactly that reason: the two conventions live in
	// this repository, a swap between them produces numbers rather than an
	// error, and a bound that has never been shown to catch one is not a
	// bound. vision_test.go's negative control is its only caller.
	Pairs bool
}

// NewRope builds the table for one image's grid.
func NewRope(cfg *Config, gridH, gridW int) *Rope {
	hd := cfg.HeadDim()
	spatial := hd / 2
	nf := spatial / 2 // 18
	inv := make([]float64, nf)
	for i := range inv {
		inv[i] = 1 / math.Pow(10000, float64(2*i)/float64(spatial))
	}
	order := blockOrder(gridH, gridW, cfg.SpatialMergeSize)
	cos := qwen.NewMat(len(order), hd)
	sin := qwen.NewMat(len(order), hd)
	for t, rc := range order {
		c, s := cos.Row(t), sin.Row(t)
		for i, f := range inv {
			ah := float64(rc[0]) * f
			aw := float64(rc[1]) * f
			// freq_hw = [h's 18 ++ w's 18]; the table is freq_hw twice.
			for _, base := range [2]int{0, spatial} {
				c[base+i] = float32(math.Cos(ah))
				s[base+i] = float32(math.Sin(ah))
				c[base+nf+i] = float32(math.Cos(aw))
				s[base+nf+i] = float32(math.Sin(aw))
			}
		}
	}
	return &Rope{Cos: cos, Sin: sin}
}

// Apply rotates every head of every row in place, NeoX halves.
func (r *Rope) Apply(x *qwen.Mat, heads, headDim int) {
	half := headDim / 2
	for t := 0; t < x.Rows; t++ {
		row := x.Row(t)
		cos, sin := r.Cos.Row(t), r.Sin.Row(t)
		for h := 0; h < heads; h++ {
			v := row[h*headDim : (h+1)*headDim]
			if r.Pairs {
				for i := 0; i < half; i++ {
					a, b := float64(v[2*i]), float64(v[2*i+1])
					v[2*i] = float32(a*float64(cos[2*i]) - b*float64(sin[2*i]))
					v[2*i+1] = float32(b*float64(cos[2*i+1]) + a*float64(sin[2*i+1]))
				}
				continue
			}
			for i := 0; i < half; i++ {
				a, b := float64(v[i]), float64(v[i+half])
				v[i] = float32(a*float64(cos[i]) - b*float64(sin[i]))
				v[i+half] = float32(b*float64(cos[i+half]) + a*float64(sin[i+half]))
			}
		}
	}
}

// Patchify turns an image into the processor's `pixel_values`: one row per
// patch, in block-major order, each row channels-then-temporal-then-pixels.
//
// img is [3, H, W] already normalized to [-1, 1] (the processor's mean and
// std are both 0.5, so that is exactly its output), and the temporal axis is
// the same frame repeated TemporalPatchSize times — a still image entering a
// video model.
func (cfg *Config) Patchify(img []float32, h, w int) (*qwen.Mat, int, int, error) {
	p := cfg.PatchSize
	gridH, gridW := h/p, w/p
	order := blockOrder(gridH, gridW, cfg.SpatialMergeSize)
	out := qwen.NewMat(len(order), cfg.PatchElems())
	plane := h * w
	for t, rc := range order {
		dst := out.Row(t)
		i := 0
		for c := 0; c < cfg.InChannels; c++ {
			for tp := 0; tp < cfg.TemporalPatchSize; tp++ {
				for py := 0; py < p; py++ {
					srcRow := (rc[0]*p + py) * w
					for px := 0; px < p; px++ {
						dst[i] = img[c*plane+srcRow+rc[1]*p+px]
						i++
					}
				}
			}
		}
	}
	return out, gridH, gridW, nil
}
	if want > 0 && len(v) != want {
		l.err = fmt.Errorf("vision: %s has %d values, want %d", name, len(v), want)
		return nil
	}
	return v
}

func (l *loader) linear(name string, out, in int) Linear {
	return Linear{In: in, Out: out,
		Weight: l.f32(name+".weight", out*in),
		Bias:   l.f32(name+".bias", out)}
}

func (l *loader) norm(name string, width int) LayerNorm {
	return LayerNorm{Weight: l.f32(name+".weight", width), Bias: l.f32(name+".bias", width)}
}

// merger loads one of the four patch mergers. `post` decides where the norm
// sits, and the norm's own width in the checkpoint is what proves it: a
// post-shuffle merger normalizes the concatenated 4608, a pre-shuffle one
// the 1152 it came from. Loading the wrong width is an error here rather
// than a wrong answer later.
func (l *loader) merger(name string, cfg *Config, post bool) Merger {
	merge := cfg.SpatialMergeSize * cfg.SpatialMergeSize
	wide := cfg.HiddenSize * merge
	normWidth := cfg.HiddenSize
	if post {
		normWidth = wide
	}
	return Merger{
		PostShuffleNorm: post,
		Merge:           merge,
		Norm:            l.norm(name+".norm", normWidth),
		FC1:             l.linear(name+".linear_fc1", wide, wide),
		FC2:             l.linear(name+".linear_fc2", cfg.OutHiddenSize, wide),
		// nn.GELU(), the exact one -- not the block MLP's tanh
		// approximation. Both are in this model and they are not the same
		// function.
		Act: geluErf,
	}
}

// Load reads the tower out of the text encoder's safetensors.
//
// `blocks` caps how many of the 27 are loaded, which is what lets a test
// walk the first two without staging 1.0 GB of ViT. Zero or negative means
// all of them; a deepstack merger whose layer is past the cap is skipped.
func Load(dir string, cfg *Config, blocks int) (*Model, error) {
	set, err := safetensors.OpenSet(dir)
	if err != nil {
		return nil, err
	}
	defer set.Close()
	if blocks <= 0 || blocks > cfg.Depth {
		blocks = cfg.Depth
	}
	l := &loader{set: set, prefix: "model.visual."}

	m := &Model{Cfg: *cfg}
	// The Conv3d patch embedding is one linear: its kernel is exactly one
	// patch, so [1152, 3, 2, 16, 16] is [1152, 1536] row-major already.
	m.PatchProj = l.linear("patch_embed.proj", cfg.HiddenSize, cfg.PatchElems())
	m.PosEmbed = l.f32("pos_embed.weight", cfg.NumPositionEmbeddings*cfg.HiddenSize)

	for i := 0; i < blocks; i++ {
		p := fmt.Sprintf("blocks.%d.", i)
		m.Blocks = append(m.Blocks, Block{
			Norm1: l.norm(p+"norm1", cfg.HiddenSize),
			Norm2: l.norm(p+"norm2", cfg.HiddenSize),
			Attn: Attention{
				QKV:      l.linear(p+"attn.qkv", 3*cfg.HiddenSize, cfg.HiddenSize),
				Proj:     l.linear(p+"attn.proj", cfg.HiddenSize, cfg.HiddenSize),
				NumHeads: cfg.NumHeads,
			},
			MLP: MLP{
				FC1: l.linear(p+"mlp.linear_fc1", cfg.IntermediateSize, cfg.HiddenSize),
				FC2: l.linear(p+"mlp.linear_fc2", cfg.HiddenSize, cfg.IntermediateSize),
				Act: geluTanh, // config hidden_act; the mergers use the erf one
			},
		})
	}
	for j, idx := range cfg.DeepstackIndexes {
		if idx >= blocks {
			continue
		}
		m.Deepstack = append(m.Deepstack, l.merger(fmt.Sprintf("deepstack_merger_list.%d", j), cfg, true))
	}
	m.Merger = l.merger("merger", cfg, false)

	if l.err != nil {
		return nil, l.err
	}
	return m, nil
}

